import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  formControlClassName,
  formErrorClassName,
  formFieldClassName,
  formLabelClassName,
  formRootClassName,
  formSubmitClassName,
} from "./view";

export {
  formControlClassName,
  formErrorClassName,
  formFieldClassName,
  formLabelClassName,
  formRootClassName,
  formSubmitClassName,
} from "./view";

export type FormStyle = Readonly<Record<string, string>>;

export type FormState = Readonly<{
  disabled?: boolean | undefined;
  invalid?: boolean | undefined;
  submitting?: boolean | undefined;
}>;

export type RootViewConfig<ParentMessage> = FormState &
  Readonly<{
    onSubmit: ParentMessage;
    children: readonly Html[];
    className?: string | undefined;
    style?: FormStyle | undefined;
  }>;

export type FieldViewConfig = FormState &
  Readonly<{
    children: readonly Html[];
    className?: string | undefined;
    style?: FormStyle | undefined;
  }>;

export type LabelViewConfig = Readonly<{
  forId: string;
  children: readonly Html[];
  className?: string | undefined;
  style?: FormStyle | undefined;
}>;

export type ControlViewConfig<ParentMessage> = FormState &
  Readonly<{
    id: string;
    value: string;
    onInput: (value: string) => ParentMessage;
    ariaLabel?: string | undefined;
    name?: string | undefined;
    type?: string | undefined;
    placeholder?: string | undefined;
    describedById?: string | undefined;
    className?: string | undefined;
    style?: FormStyle | undefined;
  }>;

export type ErrorViewConfig = Readonly<{
  id?: string | undefined;
  show: boolean;
  children: readonly Html[];
  className?: string | undefined;
  style?: FormStyle | undefined;
}>;

export type SubmitViewConfig = FormState &
  Readonly<{
    children: readonly Html[];
    className?: string | undefined;
    style?: FormStyle | undefined;
  }>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const stateAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  state: FormState
) => [
  ...(state.disabled === true ? [h.DataAttribute("disabled", "")] : []),
  ...(state.invalid === true ? [h.DataAttribute("invalid", "")] : []),
  ...(state.invalid === false ? [h.DataAttribute("valid", "")] : []),
  ...(state.submitting === true ? [h.DataAttribute("submitting", "")] : []),
];

export const rootView = <ParentMessage>({
  onSubmit,
  children,
  className,
  style,
  ...state
}: RootViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.form(
    [
      h.OnSubmit(onSubmit),
      ...stateAttributes(h, state),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(formRootClassName, className)),
    ],
    children
  );
};

export const fieldView = <ParentMessage>({
  children,
  className,
  style,
  ...state
}: FieldViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...stateAttributes(h, state),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(formFieldClassName, className)),
    ],
    children
  );
};

export const labelView = <ParentMessage>({
  forId,
  children,
  className,
  style,
}: LabelViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.label(
    [
      h.Attribute("for", forId),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(formLabelClassName, className)),
    ],
    children
  );
};

export const controlView = <ParentMessage>({
  id,
  value,
  onInput,
  ariaLabel,
  name,
  type = "text",
  placeholder,
  describedById,
  className,
  style,
  ...state
}: ControlViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.input([
    h.Id(id),
    h.Type(type),
    h.Value(value),
    h.OnInput(onInput),
    ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
    ...(name === undefined ? [] : [h.Attribute("name", name)]),
    ...(placeholder === undefined ? [] : [h.Placeholder(placeholder)]),
    ...(describedById === undefined
      ? []
      : [h.Attribute("aria-describedby", describedById)]),
    ...(state.invalid === undefined
      ? []
      : [h.Attribute("aria-invalid", state.invalid ? "true" : "false")]),
    ...(state.disabled === true ? [h.Disabled(true)] : []),
    ...stateAttributes(h, state),
    ...(style === undefined ? [] : [h.Style(style)]),
    h.Class(classNames(formControlClassName, className)),
  ]);
};

export const errorView = <ParentMessage>({
  id,
  show,
  children,
  className,
  style,
}: ErrorViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.p(
    [
      ...(id === undefined ? [] : [h.Id(id)]),
      h.Attribute("role", "alert"),
      h.AriaHidden(!show),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(formErrorClassName, className)),
    ],
    show ? children : []
  );
};

export const submitView = <ParentMessage>({
  children,
  className,
  style,
  ...state
}: SubmitViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("submit"),
      ...(state.disabled === true || state.submitting === true
        ? [h.Disabled(true)]
        : []),
      ...stateAttributes(h, state),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(formSubmitClassName, className)),
    ],
    children
  );
};

export const formRootClassName = "grid max-w-sm gap-4";

export const formFieldClassName = "grid gap-2";

export const formLabelClassName = "text-sm font-medium text-gray-950";

export const formControlClassName =
  "h-10 rounded-md border border-gray-300 bg-white px-3 text-sm text-gray-950 shadow-sm outline-none transition-colors placeholder:text-gray-400 focus:border-accent-600 focus:ring-2 focus:ring-accent-100 aria-[invalid=true]:border-red-600 aria-[invalid=true]:focus:ring-red-100 disabled:cursor-not-allowed disabled:bg-gray-50 disabled:text-gray-500";

export const formErrorClassName = "text-sm font-medium text-red-700";

export const formSubmitClassName =
  "inline-flex h-10 w-fit items-center justify-center rounded-md bg-gray-950 px-4 text-sm font-medium text-white transition-colors hover:bg-gray-800 disabled:cursor-not-allowed disabled:bg-gray-400";

import { Scene } from "foldkit";
import { html } from "foldkit/html";
import { describe, expect, test } from "vitest";

import * as Form from ".";

const view = (value: string, invalid = false) => {
  const h = html<string>();

  return Form.rootView<string>({
    onSubmit: "submitted",
    invalid,
    children: [
      Form.fieldView({
        invalid,
        children: [
          Form.labelView({
            forId: "homepage",
            children: [h.span([], ["Homepage"])],
          }),
          Form.controlView({
            id: "homepage",
            name: "homepage",
            type: "url",
            value,
            onInput: (nextValue) => nextValue,
            ariaLabel: "Homepage",
            describedById: "homepage-error",
            invalid,
          }),
          Form.errorView({
            id: "homepage-error",
            show: invalid,
            children: [h.span([], ["Use a domain other than example.com"])],
          }),
        ],
      }),
      Form.submitView({ children: [h.span([], ["Submit"])] }),
    ],
  });
};

describe("Form registry component", () => {
  test("renders labelled control, submit, and error state", () => {
    Scene.scene(
      {
        update: (model: string, message: string) => [message, []] as const,
        view: (value) => view(value, true),
      },
      Scene.with("https://example.com"),
      Scene.expect(Scene.role("textbox", { name: "Homepage" })).toHaveValue(
        "https://example.com"
      ),
      Scene.expect(Scene.role("textbox", { name: "Homepage" })).toHaveAttr(
        "aria-invalid",
        "true"
      ),
      Scene.expect(Scene.text("Use a domain other than example.com")).toExist(),
      Scene.click(Scene.role("button", { name: "Submit" })),
      Scene.expect(Scene.role("textbox", { name: "Homepage" })).toHaveValue(
        "submitted"
      )
    );
  });

  test("exports Base UI form class hooks", () => {
    expect(Form.formRootClassName).toContain("grid");
    expect(Form.formControlClassName).toContain("aria-[invalid=true]");
  });
});
